'use strict';
(function(){const list=document.getElementById('plasma-x-posts'),status=document.getElementById('plasma-x-feed-status'),reload=document.getElementById('reload-x-feed');if(!list)return;let busy=false;const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n;};const decode=value=>{const t=document.createElement('textarea');t.innerHTML=value;return t.value;};async function load(){if(busy)return;busy=true;reload.disabled=true;try{const r=await fetch('/api/x-feed',{signal:AbortSignal.timeout(18000)}),data=await r.json();if(!r.ok)throw Error(data.error||'The feed could not load.');const fragment=document.createDocumentFragment();for(const p of data.posts){const card=el('article',null,'x-feed-post'),head=el('div',null,'x-feed-author');if(p.author.avatar){const img=el('img');img.src=p.author.avatar;img.alt='';img.loading='lazy';head.append(img);}const byline=el('div');byline.append(el('strong',p.author.name),el('span','@'+p.author.username));head.append(byline);card.append(head,el('p',decode(p.text),'x-feed-text'));if(p.images?.length){const gallery=el('div',null,'x-feed-images');for(const url of p.images){const img=el('img');img.src=url;img.alt='Image attached to the post';img.loading='lazy';gallery.append(img);}card.append(gallery);}const date=new Date(p.createdAt);if(!isNaN(date)){const time=el('time',date.toLocaleString());time.dateTime=date.toISOString();card.append(time);}if(p.video){const a=el('a','Watch video on PlasmaX');a.href='/x/?url='+encodeURIComponent('https://x.com/'+p.author.username+'/status/'+p.id);card.append(a);}fragment.append(card);}list.replaceChildren(fragment);status.textContent=data.posts.length?'Posts checked '+new Date(data.checkedAt).toLocaleTimeString()+'.':'X returned no public posts for this account.';}catch(e){status.textContent=e.message||'The feed could not load. Try reloading.';}finally{busy=false;reload.disabled=false;}}reload.addEventListener('click',load);document.addEventListener('visibilitychange',()=>{if(!document.hidden)load();});setInterval(()=>{if(!document.hidden)load();},60000);load();})();
